Lemma pv_out_short : forall bs, (length bs < 8)%nat -> pv_out bs = mkPV 0 None (Some (HE_NEED_MORE, ALOC_PV_NM)).
Proof.
  intros bs H.
  destruct bs as [|c0 [|c1 [|c2 [|c3 [|c4 [|c5 [|c6 [|c7 rest]]]]]]]]; try reflexivity. cbn in H. lia.
Qed.
